<?php
$root=getenv('P20_ROOT');$companyId=(int)getenv('P20_COMPANY_ID');if(!$root||$companyId<=0){fwrite(STDERR,"args\n");exit(2);}chdir($root);$config=require $root.'/bootstrap/app.php';require_once $root.'/app/Core/Database.php';require_once $root.'/app/Support/crypto_helper.php';require_once $root.'/app/Support/company_database.php';
$central=(new App\Core\Database($config['database']))->connection();$st=$central->prepare('SELECT * FROM companies WHERE id=?');$st->execute([$companyId]);$company=$st->fetch(PDO::FETCH_ASSOC);if(!$company){throw new RuntimeException('company missing');}$pdo=(new App\Core\Database(companyDatabaseConfig($config,$company)))->connection();$tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);sort($tables,SORT_STRING);$rows=[];foreach($tables as $t){$q='`'.str_replace('`','``',$t).'`';$create=$pdo->query('SHOW CREATE TABLE '.$q)->fetch(PDO::FETCH_NUM);$count=(int)$pdo->query('SELECT COUNT(*) FROM '.$q)->fetchColumn();$checksum=$pdo->query('CHECKSUM TABLE '.$q)->fetch(PDO::FETCH_ASSOC);$rows[]=['table'=>$t,'create'=>$create[1]??'','count'=>$count,'checksum'=>$checksum['Checksum']??null];}echo hash('sha256',json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)),PHP_EOL;
